CREATE TABLE IF NOT EXISTS governance_resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resolution_number text NOT NULL UNIQUE, resolution_type text NOT NULL, title text NOT NULL, status text NOT NULL DEFAULT 'draft', meeting_date date, effective_date date, proposed_by text, approved_by text, approval_notes text, resolution_text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS governance_meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_type text NOT NULL, title text NOT NULL, meeting_date date NOT NULL, location_or_mode text, chairperson text, status text NOT NULL DEFAULT 'scheduled', agenda text, minutes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS corporate_register_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), register_type text NOT NULL, item_name text NOT NULL, reference_number text, status text NOT NULL DEFAULT 'active', details text, review_date date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_governance_resolutions_status ON governance_resolutions(status,meeting_date);
CREATE INDEX IF NOT EXISTS idx_governance_meetings_date ON governance_meetings(meeting_date,status);
CREATE INDEX IF NOT EXISTS idx_corporate_register_type ON corporate_register_items(register_type,status);